/* ============================================
   SITE LAYOUT COMPONENT
   The frame of a documentation or marketing site:
   header, sidebar, main, aside and footer, laid out
   by two independent choices, the page's width
   (the shell recipe's width axis) and where the
   sidebar docks. No surface of its own, not even
   the page colour: what lies behind shows through.
   ============================================ */

.ds-site-layout {
  /* The header's height, the same calc SiteHeader uses for its bar, so the
     sticky columns start below it. An override hook for another header. */
  --ds-site-layout-header-height: calc(var(--control-height-default) + var(--padding-1000));
  /* The window's height, an override hook for a host that pins it (a page
     drawn in a scaled preview frame sets its own). */
  --ds-site-layout-viewport-height: 100vh;
  /* Column widths: room for a page title or a section name on one line. */
  --ds-site-layout-sidebar-width: calc(6.5 * var(--control-height-default));
  --ds-site-layout-aside-width: calc(5 * var(--control-height-default));
  /* The reading width of `readingWidth`: about 75 characters of body text. */
  --ds-site-layout-reading-width: calc(19 * var(--control-height-default));
  /* Room the page gives up at its end edge, for a panel the host docks
     there (a chat): the whole frame, header included, steps in by it, and
     an edge-pinned aside moves in with it. 0 by default. */
  --ds-site-layout-reserve-end: 0px;
  /* The room between the header and the page, the site's own page rhythm:
     the sidebar, the main column and the aside all start this far down. */
  --ds-site-layout-top-gap: var(--gap-1500);
  /* A heading jump lands clear of the sticky header and of the blur that
     fades out below its bar (SiteHeader's --ds-site-header-blur-reach,
     --gap-1500), with a beat to spare, so the heading is never cut off. */
  --ds-heading-scroll-margin: calc(
    var(--ds-site-layout-header-height) + var(--ds-site-header-blur-reach, var(--gap-1500)) + var(--gap-200)
  );
  display: flex;
  flex-direction: column;
  /* The whole width of whatever holds it, a flex parent that centres its
     children included: the frame is the page, never a column in one. */
  align-self: stretch;
  width: 100%;
  box-sizing: border-box;
  min-height: var(--ds-site-layout-viewport-height);
  padding-inline-end: var(--ds-site-layout-reserve-end);
  transition: padding-inline-end var(--motion-duration-slow) var(--motion-ease-emphasized);
  /* No background: the page behind is the floor, so an ambient field or a
     shader the host paints there shows through the frame. */
}

/* A frame that reaches the window's edges (docked to the edge, or a full
   page) keeps a wider gutter from the tablet step up, so the brand and the
   sidebar's words sit well in from the edge and a row's hanging fill keeps
   room before it. The header's slot and the footer's row inherit it, so all
   three still share one line. --ds-site-layout-edge-gutter overrides it. */
@media (min-width: 960px) {
  .ds-site-layout--dock-edge,
  .ds-site-layout[data-ds-width='full'] {
    --ds-shell-gutter: var(--ds-site-layout-edge-gutter, calc(var(--padding-500) + var(--padding-300)));
  }
}

/* ============================================
   HEADER
   The header's slot draws no box, so a sticky
   header sticks to the whole page; it carries the
   header's width axis, which a SiteHeader with no
   width of its own reads.
   ============================================ */

.ds-site-layout__header {
  display: contents;
}

.ds-site-layout__header > .ds-site-header:not(.ds-site-header--width) .ds-site-header__bar {
  max-width: var(--ds-shell-content-max, var(--ds-shell-contained-width));
  margin-inline: auto;
  padding-inline: var(--ds-shell-gutter);
}

/* ============================================
   BODY AND ROW
   The row is the width axis: contained, it centres
   at the contained width; full, it runs edge to
   edge. Docked to the content, the sidebar is the
   row's first column; docked to the edge, it sits
   before the row and the row takes the room after.
   ============================================ */

.ds-site-layout__body {
  display: flex;
  flex: 1 0 auto;
  width: 100%;
  min-width: 0;
}

.ds-site-layout__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  /* The site's column gap, the room between a page's columns. */
  gap: var(--gap-1500);
  flex: 1 1 auto;
  min-width: 0;
  max-width: var(--ds-shell-content-max, var(--ds-shell-contained-width));
  margin-inline: auto;
  padding-inline: var(--ds-shell-gutter);
  box-sizing: border-box;
}

.ds-site-layout--dock-content.ds-site-layout--with-sidebar .ds-site-layout__row {
  grid-template-columns: var(--ds-site-layout-sidebar-width) minmax(0, 1fr);
}

.ds-site-layout--with-aside .ds-site-layout__row {
  grid-template-columns: minmax(0, 1fr) var(--ds-site-layout-aside-width);
}

.ds-site-layout--dock-content.ds-site-layout--with-sidebar.ds-site-layout--with-aside .ds-site-layout__row {
  grid-template-columns: var(--ds-site-layout-sidebar-width) minmax(0, 1fr) var(--ds-site-layout-aside-width);
}

/* ============================================
   SIDEBAR
   Sticks below the header and holds the window's
   height, so a scrollable NavList inside scrolls on
   its own. Docked to the edge it carries the gutter
   on its start side and a hairline on its end.
   ============================================ */

.ds-site-layout__sidebar {
  position: sticky;
  top: var(--ds-site-layout-header-height);
  display: flex;
  flex-direction: column;
  align-self: start;
  height: calc(var(--ds-site-layout-viewport-height) - var(--ds-site-layout-header-height));
  min-height: 0;
  /* Its list starts the top gap down, and scrolls up through it. */
  padding-block-start: var(--ds-site-layout-top-gap);
  box-sizing: border-box;
}

.ds-site-layout--dock-edge .ds-site-layout__sidebar {
  position: sticky;
  flex: none;
  width: calc(var(--ds-site-layout-sidebar-width) + var(--ds-shell-gutter));
  padding-inline: var(--ds-shell-gutter) var(--padding-300);
}

/* Optical alignment: a NavList's words line up with the header's brand,
   not its row fills, so the list hangs out by its own text inset and the
   fills sit in the gutter. A host's own list sets the same hook to join in. */
.ds-site-layout__sidebar > .ds-nav-list,
.ds-site-layout__sidebar > [data-ds-sidebar-hang] {
  width: calc(100% + var(--ds-nav-list-text-inset, 0px));
  margin-inline-start: calc(-1 * var(--ds-nav-list-text-inset, 0px));
}

/* Docked to the edge, the content sits the column gap off the divider,
   not the gutter, so it never crowds the sidebar, and takes the same gap
   at the window's end, so it centres between the two edges (an edge-pinned
   aside sits in that end margin). */
.ds-site-layout--dock-edge.ds-site-layout--with-sidebar .ds-site-layout__row {
  padding-inline: var(--gap-1500);
}

/* An edge-pinned aside floats over the window's end margin, so the row
   keeps room for it: the gutter it sits in, the rail itself (about a
   control's height wide) and a beat. A contained row takes only the part
   of that room its own margin does not already give (100% is the body's
   width; docked to the edge, the sidebar's column comes off it first; a
   window narrower than the contained width leaves no margin), so a
   wide window keeps the full contained width; a full row takes all of it. */
.ds-site-layout {
  --ds-site-layout-rail-room: calc(var(--ds-shell-gutter) + var(--control-height-default) + var(--gap-500));
}

.ds-site-layout.ds-site-layout--aside-edge[data-ds-width='contained'] .ds-site-layout__row {
  padding-inline-end: max(
    var(--ds-shell-gutter),
    calc(var(--ds-site-layout-rail-room) - max(0px, (100% - var(--ds-shell-contained-width)) / 2))
  );
}

.ds-site-layout.ds-site-layout--aside-edge.ds-site-layout--dock-edge[data-ds-width='contained'] .ds-site-layout__row {
  padding-inline-end: max(
    var(--gap-1500),
    calc(
      var(--ds-site-layout-rail-room) -
        max(
          0px,
          (100% - var(--ds-site-layout-sidebar-width) - var(--ds-shell-gutter) - var(--ds-shell-contained-width)) / 2
        )
    )
  );
}

.ds-site-layout.ds-site-layout--aside-edge[data-ds-width='full'] .ds-site-layout__row {
  padding-inline-end: max(var(--gap-1500), var(--ds-site-layout-rail-room));
}

/* The edge-docked sidebar's divider: a hairline that fades out at both
   ends, so it reads as a seam between the sidebar and the page rather than
   a box drawn around the list. */
.ds-site-layout--dock-edge .ds-site-layout__sidebar::after {
  content: '';
  position: absolute;
  /* From where the list starts, not from the header's edge. */
  inset-block: var(--ds-site-layout-top-gap) 0;
  inset-inline-end: 0;
  width: var(--border-025);
  background: linear-gradient(
    to bottom,
    transparent,
    var(--color-divider) var(--gap-1000),
    var(--color-divider) calc(100% - var(--gap-1000)),
    transparent
  );
  pointer-events: none;
}

/* ============================================
   MAIN AND ASIDE
   ============================================ */

.ds-site-layout__main {
  display: flex;
  flex-direction: column;
  gap: var(--gap-500);
  min-width: 0;
  padding-block: var(--ds-site-layout-top-gap) var(--padding-1500);
  outline: none;
}

/* readingWidth: the main column holds the measure, centred in its grid
   cell, while the page is contained; full sets the shell maximum to none.
   The main element itself narrows, never its children, so a fixed control
   inside it (BackToTop, a docked panel) keeps its own placement. */
.ds-site-layout--reading .ds-site-layout__main {
  width: 100%;
  max-width: var(--ds-shell-content-max, var(--ds-site-layout-reading-width));
  justify-self: center;
  box-sizing: border-box;
}

.ds-site-layout__aside {
  position: sticky;
  top: var(--ds-site-layout-header-height);
  align-self: start;
  padding-block-start: var(--ds-site-layout-top-gap);
}

/* Pinned to the window's end edge (asidePlacement="edge"): out of the
   grid, centred on the height, a gutter in from the edge, so the content
   keeps the room a column would take. It moves in with the end reserve. */
.ds-site-layout--aside-edge .ds-site-layout__aside {
  position: fixed;
  inset-block-start: 50%;
  /* Fixed to the window, so it follows the end reserve, not the frame's
     box. A host that narrows the page itself rather than through the
     reserve (padding on the body for a docked chat) moves it with
     --ds-site-layout-aside-inset instead. */
  inset-inline-end: var(
    --ds-site-layout-aside-inset,
    calc(var(--ds-site-layout-reserve-end) + var(--ds-shell-gutter))
  );
  padding-block-start: 0;
  transform: translateY(-50%);
  /* Above the page's content, below the sticky header and its menus. */
  z-index: 5;
  transition: inset-inline-end var(--motion-duration-slow) var(--motion-ease-emphasized);
}

/* ============================================
   FOOTER
   A fading hairline above, the width axis inside.
   ============================================ */

.ds-site-layout__footer {
  position: relative;
  /* Room between the page and the footer, so the body (the sidebar's last
     rows included) ends well clear of the line above it. */
  margin-block-start: var(--gap-2000);
}

/* The line above the footer fades out at both ends, the sidebar divider's
   treatment turned on its side. */
.ds-site-layout__footer::before {
  content: '';
  position: absolute;
  inset-block-start: 0;
  inset-inline: 0;
  height: var(--border-025);
  background: linear-gradient(
    to right, /* ds-allow(physical): a symmetric fade, the same at both ends in either reading direction */
    transparent,
    var(--color-divider) var(--gap-1500),
    var(--color-divider) calc(100% - var(--gap-1500)),
    transparent
  );
  pointer-events: none;
}

.ds-site-layout__footer-row {
  max-width: var(--ds-shell-content-max, var(--ds-shell-contained-width));
  margin-inline: auto;
  padding-inline: var(--ds-shell-gutter);
  box-sizing: border-box;
}

/* ============================================
   RESPONSIVE
   Below 1152px a column aside gives way; below
   960px the sidebar and an edge aside leave the
   page, and the header's menu carries the pages.
   ============================================ */

@media (max-width: 1151px) {
  /* The column aside only: an edge-pinned one takes no column, so it stays
     until the sidebar goes. */
  .ds-site-layout--with-aside .ds-site-layout__aside {
    display: none;
  }

  .ds-site-layout--with-aside .ds-site-layout__row {
    grid-template-columns: minmax(0, 1fr);
  }

  .ds-site-layout--dock-content.ds-site-layout--with-sidebar.ds-site-layout--with-aside .ds-site-layout__row {
    grid-template-columns: var(--ds-site-layout-sidebar-width) minmax(0, 1fr);
  }
}

@media (max-width: 959px) {
  .ds-site-layout__sidebar,
  .ds-site-layout--aside-edge .ds-site-layout__aside {
    display: none;
  }

  /* The sidebar's room and gap go with it: the content takes the header's
     gutter, so it lines up with the brand above it. */
  .ds-site-layout.ds-site-layout .ds-site-layout__row {
    grid-template-columns: minmax(0, 1fr);
    padding-inline: var(--ds-shell-gutter);
  }

  /* The edge aside is gone too, and its room with it. */
  .ds-site-layout.ds-site-layout--aside-edge[data-ds-width] .ds-site-layout__row,
  .ds-site-layout.ds-site-layout--aside-edge.ds-site-layout--dock-edge[data-ds-width] .ds-site-layout__row {
    padding-inline-end: var(--ds-shell-gutter);
  }
}

'use client';

import React from 'react';
import { Link } from '../Link/Link';
import '../../behaviors/shell.css';
import './SiteLayout.css';

/** Props owned by SiteLayout itself. */
type SiteLayoutOwnProps = {
  /** The page's main content: the article, the page. */
  children: React.ReactNode;
  /**
   * The top bar, usually a SiteHeader. A SiteHeader given no `width` of its
   * own follows `headerWidth`, so the bar lines up with the page below it.
   */
  header?: React.ReactNode;
  /**
   * The navigation column, usually a scrollable NavList: the wide-screen
   * form of the site's sub-navigation. Sticks below the header; below
   * 960px it leaves the page, and the header's own menu carries the same
   * pages (give each SiteHeader section its `drawerItems`), so a reader has
   * one menu, never two.
   */
  sidebar?: React.ReactNode;
  /** The column after the content, usually an AnchorNav reading the page's headings. Gives way below 1152px in the `column` placement. */
  aside?: React.ReactNode;
  /**
   * Where the aside sits. `column` gives it a column of its own after the
   * content. `edge` pins it to the window's end edge, centred on the
   * height, and gives the content the room: the place for AnchorNav's
   * `floating` variant, a minimap that opens on hover or focus. Hidden
   * below 960px in either.
   */
  asidePlacement?: 'column' | 'edge';
  /** The bottom of the site, usually a SiteFooter. */
  footer?: React.ReactNode;
  /**
   * How wide the page runs, the shell recipe's width axis. `contained`
   * centres the columns at the contained width (1440px, or the nearest
   * `--ds-shell-contained-width`); `full` runs them edge to edge, the side
   * gutter aside.
   */
  width?: 'contained' | 'full';
  /**
   * The contained width's step, for a page a level narrower or wider than
   * the default: `narrow` (1200px, a 1080px article beside an edge-docked sidebar), `default` (1440px) or `wide` (1680px).
   * The header and the footer follow it when contained. With the sidebar
   * docked to the edge, the step caps the room after the sidebar; docked to
   * the content, it caps the sidebar and the content together.
   * @default 'default'
   */
  containedWidth?: 'narrow' | 'default' | 'wide';
  /**
   * How wide the header's bar runs, for a SiteHeader that sets no `width`
   * of its own. It moves with the sidebar's dock: `full` when the sidebar
   * docks to the window's edge (so the brand sits over the sidebar, flush
   * with the same edge), the page's `width` when it docks beside the
   * content. Set it only to break that pairing.
   * @default sidebarDock === 'edge' ? 'full' : width
   */
  headerWidth?: 'contained' | 'full';
  /**
   * How wide the footer's row runs. It moves with the header: `full` when
   * the sidebar docks to the window's edge, the page's `width` when it
   * docks beside the content, so the top and the bottom of the site always
   * agree. Set it only to break that pairing.
   * @default sidebarDock === 'edge' ? 'full' : width
   */
  footerWidth?: 'contained' | 'full';
  /**
   * Where the sidebar sits. `content` keeps it in the page's row, beside the
   * content, so a contained page centres all three columns together. `edge`
   * docks it to the window's start edge behind a hairline, and the content
   * and aside are laid out (and contained) in the room after it.
   */
  sidebarDock?: 'content' | 'edge';
  /**
   * Hold the main column to a reading width (about 75 characters of body
   * text, centred in its column) while the page is contained. A full-width page lets the content run the whole column.
   * `--ds-site-layout-reading-width` sets the measure.
   */
  readingWidth?: boolean;
  /** The id of the main region, the skip link's target. */
  mainId?: string;
  /** The skip link's text, the page's first stop. Pass an empty string for none. */
  skipLinkLabel?: string;
  /** Accessible name of the sidebar's navigation landmark. */
  sidebarLabel?: string;
  /** Accessible name of the aside's complementary landmark. */
  asideLabel?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface SiteLayoutProps
  extends SiteLayoutOwnProps,
    Omit<React.ComponentPropsWithRef<'div'>, keyof SiteLayoutOwnProps> {}

/**
 * SiteLayout: the frame of a documentation or marketing site. A header, a
 * navigation sidebar, the main content, an aside and a footer, laid out by
 * props: how wide the page runs (`width`, stepped by `containedWidth`),
 * where the sidebar docks (`sidebarDock`; the header and the footer move
 * with it unless `headerWidth` or `footerWidth` breaks the pairing), where
 * the aside sits (`asidePlacement`) and the reading width; any combination
 * holds. The sidebar sticks below the header and scrolls on its own; below
 * 1152px a column aside gives way, and below 960px the sidebar and an edge
 * aside leave the page to the header's own menu. A skip link comes first.
 */
export function SiteLayout({
  children,
  header,
  sidebar,
  aside,
  footer,
  width = 'contained',
  containedWidth = 'default',
  headerWidth,
  footerWidth,
  readingWidth = false,
  sidebarDock = 'content',
  asidePlacement = 'column',
  mainId = 'main',
  skipLinkLabel = 'Skip to content',
  sidebarLabel = 'Pages',
  asideLabel = 'On this page',
  className = '',
  ref,
  ...rest
}: SiteLayoutProps) {
  const baseClass = 'ds-site-layout';
  // The frame moves as one: an edge-docked sidebar takes the header and the
  // footer to the window's edges with it; docked beside the content, both
  // follow the page.
  const frameWidth = sidebarDock === 'edge' ? 'full' : width;
  const classes = [
    baseClass,
    `${baseClass}--dock-${sidebarDock}`,
    sidebar ? `${baseClass}--with-sidebar` : '',
    aside && asidePlacement === 'column' ? `${baseClass}--with-aside` : '',
    aside && asidePlacement === 'edge' ? `${baseClass}--aside-edge` : '',
    readingWidth ? `${baseClass}--reading` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  const content = (
    <>
      <main id={mainId} className={`${baseClass}__main`} tabIndex={-1}>
        {children}
      </main>
      {aside && (
        <aside className={`${baseClass}__aside`} aria-label={asideLabel}>
          {aside}
        </aside>
      )}
    </>
  );
  const sidebarColumn = sidebar && (
    <nav className={`${baseClass}__sidebar`} aria-label={sidebarLabel}>
      {sidebar}
    </nav>
  );

  return (
    <div
      {...rest}
      ref={ref}
      className={classes}
      data-ds-width={width}
      data-ds-contained={containedWidth === 'default' ? undefined : containedWidth}
    >
      {skipLinkLabel && (
        <Link variant="skip" href={`#${mainId}`}>
          {skipLinkLabel}
        </Link>
      )}
      {header && (
        <div className={`${baseClass}__header`} data-ds-width={headerWidth ?? frameWidth}>
          {header}
        </div>
      )}
      {sidebarDock === 'edge' ? (
        <div className={`${baseClass}__body`}>
          {sidebarColumn}
          <div className={`${baseClass}__row`}>{content}</div>
        </div>
      ) : (
        <div className={`${baseClass}__body`}>
          <div className={`${baseClass}__row`}>
            {sidebarColumn}
            {content}
          </div>
        </div>
      )}
      {footer && (
        <div className={`${baseClass}__footer`} data-ds-width={footerWidth ?? frameWidth}>
          <div className={`${baseClass}__footer-row`}>{footer}</div>
        </div>
      )}
    </div>
  );
}
